import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"Module 9 · Property deeds","description":"","frontmatter":{},"headers":[],"relativePath":"modules/09-property-deeds.md","filePath":"modules/09-property-deeds.md","lastUpdated":1790431304000}'),n={name:"modules/09-property-deeds.md"};function r(o,e,h,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="module-9-·-property-deeds" tabindex="-1">Module 9 · Property deeds <a class="header-anchor" href="#module-9-·-property-deeds" aria-label="Permalink to &quot;Module 9 · Property deeds&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>PropertyDeeds.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Housing</td></tr><tr><td><strong>Standard</strong></td><td>ERC-721, plus a certification flag</td></tr><tr><td><strong>Stamp</strong></td><td>Module 9</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Land registration is one of the oldest uses of writing, and it is still hard. Who owns this house? The answer lives in a government register, and in much of the world that register is incomplete, contested, slow to search, or corruptible. Title fraud — forging a transfer of someone else&#39;s property — is a real crime with real victims.</p><p>&quot;Put land titles on a blockchain&quot; is therefore one of the most frequently proposed applications, and one of the most frequently misunderstood. This module builds it <em>and</em> shows you exactly where it breaks.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>A deed is an NFT. Transferring the token transfers the record of ownership, and the history of transfers is public and append-only.</p><p>Then one extra idea that makes the module honest: <strong>certification</strong>. The town can vouch that a particular owner really holds a particular property — and that vouching is automatically thrown away the moment the token moves.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Deed.</strong> A document evidencing ownership of land. Note &quot;evidencing&quot;: the deed is not the land, and this distinction is the whole module.</p><p><strong>Certification.</strong> A statement by an authority that a record matches reality. Here it is a single boolean set by <code>CERTIFIER_ROLE</code>.</p><p><strong>The registry gap.</strong> The difference between what a register says and what the law recognises. On chain, this is the gap between the token holder and the legal owner.</p><p><strong>Transfer hook.</strong> Code that runs on every token movement. In OpenZeppelin v5 this is <code>_update</code>, and overriding it is how a token adds behaviour to transfers.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Property</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> registrant;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> registeredAt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> certified;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> addressLine;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docHash;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// hash of the off-chain title document</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What</th></tr></thead><tbody><tr><td><code>register(addressLine, docHash)</code></td><td>any resident</td><td>Mints the deed to the caller</td></tr><tr><td><code>certify(id)</code></td><td><code>CERTIFIER_ROLE</code></td><td>The town vouches for this owner</td></tr><tr><td><code>transferFrom</code> / <code>safeTransferFrom</code></td><td>the owner</td><td>Standard ERC-721</td></tr><tr><td><code>get(id)</code></td><td>anyone</td><td>The record</td></tr><tr><td><code>tokenURI(id)</code></td><td>anyone</td><td>On-chain JSON, including certification</td></tr></tbody></table><p>Anyone registered as a resident can register any property, with any address line. The contract does not know what land exists.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>Certification does not survive a transfer:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> _update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">internal</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> override</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> returns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> from </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> super</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">_update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(to, id, auth);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (from </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> to </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _props[id].certified) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        _props[id].certified </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        emit</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CertificationCleared</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(id, from);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> from;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Read what this says. The town certified that <strong>Alice</strong> owns 14 Mill Lane. Alice sells the token to Bob. The chain now records Bob as holder — but the town never said anything about Bob, so the certification is cleared and an event announces it.</p><p>This is the module&#39;s central lesson, and it is worth stating twice: <strong>the chain can move the token perfectly and still be wrong about the world.</strong> A token transfer is not a conveyance. It has no searches, no mortgage discharge, no signatures witnessed, no stamp duty, no recourse if the seller had no right to sell. The certification flag is the town admitting that only an off-chain process can connect the two, and clearing the flag is the contract refusing to pretend otherwise.</p><p>Compare with module 2&#39;s Passport, which cannot move at all, and module 8&#39;s tickets, which move freely and carry everything with them. Deeds are the interesting middle: the token moves, but a piece of its meaning does not.</p><p><strong>The zero-address conditions matter.</strong> Minting (<code>from == 0</code>) must not clear a flag that was never set, and burning (<code>to == 0</code>) need not bother. Getting these guards wrong is a common source of subtle bugs in transfer hooks.</p><p><strong><code>docHash</code> again.</strong> As in module 7, the document stays off chain and only its hash is anchored. A title deed is full of names and addresses; publishing it would be a data protection incident, not a feature.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Register a property. You hold the deed.</li><li>Look at <code>tokenURI</code> on the explorer. Certified: no.</li><li>Ask the instructor (who holds <code>CERTIFIER_ROLE</code>) to certify it. Look again: yes.</li><li>Transfer the deed to a classmate.</li><li>Look a third time. Certified: no — and there is a <code>CertificationCleared</code> event saying so.</li><li>Register &quot;Buckingham Palace&quot; as a property. Nothing stops you. Note that the chain will keep that claim, with your address on it, for ever.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transfer(from: 0x0, to: registrant, tokenId: 3)         // ERC-721 mint</span></span>
<span class="line"><span>PropertyRegistered(id: 3, registrant: 0x…, addressLine: &quot;14 Mill Lane&quot;, docHash: 0x…)</span></span>
<span class="line"><span>Stamped(tokenId: …, moduleId: 9, by: propertyDeeds)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>PropertyCertified(id: 3, by: certifier, owner: 0x…)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Transfer(from: owner, to: buyer, tokenId: 3)</span></span>
<span class="line"><span>CertificationCleared(id: 3, previousOwner: 0x…)</span></span></code></pre></div><p>The <code>Transfer</code> and <code>CertificationCleared</code> events are emitted by the same transaction, in that order, because the hook runs inside the transfer. Reading them in order is how an indexer keeps its view of certification correct.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>For an actual land registry, a database — essentially always, today. A registry needs to correct errors, enforce court orders, handle inheritance and incapacity, redact personal data, and answer to a legal system. Every one of those is something a public immutable ledger is bad at.</p><p>The honest cases where a chain adds something:</p><ul><li><strong>Fractional or tokenised property interests</strong> that trade often, where the token <em>is</em> the asset rather than evidence of one.</li><li><strong>Registries in jurisdictions where the state register is the threat</strong> — though note that a chain does not stop a government from simply not recognising it.</li><li><strong>Audit trails alongside</strong> a conventional register, anchoring its state so that silent revision becomes detectable.</li></ul><p>Several countries have piloted land registries on chains. The pattern in the results is consistent: the technology worked and the institutional problem remained.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Legal ownership.</strong> A court decides that, and it has never heard of your token.</li><li><strong>Lost keys.</strong> Lose the key and you lose the deed, with no registrar to appeal to. For a house, this is a serious objection rather than an inconvenience.</li><li><strong>Duplicate registrations.</strong> Two people can register the same address. The contract cannot tell.</li><li><strong>Theft by signature.</strong> If someone gets your key, the fraudulent transfer is final and looks exactly like a legitimate one.</li><li><strong>What the property is.</strong> A string. Not a survey, not coordinates, not a boundary.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Treating the token as the title.</strong> The single biggest conceptual error in this space.</li><li><strong>Letting certification travel with the token.</strong> Then a certified deed can be sold to anyone and the certification means nothing.</li><li><strong>Forgetting the mint and burn cases in the hook.</strong> <code>from == 0</code> and <code>to == 0</code> need handling.</li><li><strong>Putting the deed document on chain.</strong> Personal data, permanently public.</li><li><strong>No way to correct an error.</strong> Real registries need rectification. Decide deliberately whether yours has it, and who can use it.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can a non-certifier certify? Can a certifier un-certify at will?</li><li>[ ] Does certification survive a transfer? A transfer back?</li><li>[ ] Can the same address line be registered twice?</li><li>[ ] Can a deed be burned, and what happens to a lease that depends on it (module 10)?</li><li>[ ] Who can <code>approve</code> a transfer, and does that bypass any of your checks?</li><li>[ ] If a key is lost, is there any recovery path at all — and should there be?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Add a rectification function for the registrar, then write down exactly who may call it and what stops it being a back door. You have just rediscovered why land registries have procedure.</li><li>Require certification before a deed may be transferred, and see what that does to the market — and to the registrar&#39;s power.</li><li>Add a mortgage lien: a second party who must consent to a transfer. Model it as a flag, then as an approval, then argue about which is right.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://eips.ethereum.org/EIPS/eip-721" target="_blank" rel="noreferrer">ERC-721</a></li><li><a href="https://docs.openzeppelin.com/contracts/5.x/api/token/erc721#ERC721-_update-address-uint256-address-" target="_blank" rel="noreferrer">OpenZeppelin ERC721 <code>_update</code></a></li><li>Search for published evaluations of blockchain land registry pilots, and read the conclusions rather than the announcements.</li></ul><p><strong>Next:</strong> <a href="./10-rent-escrow">Module 10 · Rent escrow →</a></p>`,46)])])}const g=t(n,[["render",r]]);export{k as __pageData,g as default};
